def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')

    if not uri or uri.strip() == '':
        raise ValueError('uri is empty')

    uri = uri.strip()

    # Parse the URI
    parsed = urlparse.urlparse(uri)

    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri has no scheme')

    scheme = scheme.lower()

    netloc = parsed.netloc
    path = parsed.path

    # Override host if provided
    if host is not None:
        netloc = host

    if not netloc:
        raise ValueError('uri has no host')

    # Separate userinfo from host
    if '@' in netloc:
        netloc = netloc.split('@', 1)[1]

    # Split host and port
    # Handle IPv6 addresses
    if netloc.startswith('['):
        # IPv6
        bracket_end = netloc.find(']')
        if bracket_end == -1:
            raise ValueError('invalid IPv6 address')
        host_part = netloc[:bracket_end + 1]
        rest = netloc[bracket_end + 1:]
        if rest.startswith(':'):
            port_str = rest[1:]
        else:
            port_str = None
    elif ':' in netloc:
        # Check for multiple colons (invalid for non-IPv6)
        parts = netloc.split(':')
        if len(parts) > 2:
            raise ValueError('invalid host:port')
        host_part = parts[0]
        port_str = parts[1]
    else:
        host_part = netloc
        port_str = None

    if not host_part:
        raise ValueError('uri has no host')

    # Validate and process port
    default_ports = {'http': '80', 'https': '443'}

    if port_str is not None:
        if port_str == '':
            # Empty port - treat as no port
            port_str = None
        else:
            # Validate port
            try:
                port_num = int(port_str)
            except ValueError:
                raise ValueError('invalid port: ' + port_str)

            if port_num <= 0 or port_num > 65535:
                raise ValueError('invalid port number: ' + port_str)

            # Remove default port
            if default_ports.get(scheme) == port_str:
                port_str = None

    # Reconstruct netloc
    host_part = host_part.lower()

    # Percent-encode the host if needed
    if ' ' in host_part:
        host_part = urlparse.quote(host_part, safe='[].:')

    if port_str is not None:
        netloc = host_part + ':' + port_str
    else:
        netloc = host_part

    # Process path
    if not path:
        path = '/'

    # Percent-encode spaces in path
    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@%')

    # Reconstruct URI without query and fragment
    result = scheme + '://' + netloc + path

    return result
